.profile-layout {
    display: flex;
    gap: 2rem;
    margin-bottom: 1.5rem;
}

.avatar-area {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    min-width: 120px;
}

.avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    background: var(--bs-tertiary-bg, #e9ecef);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    border: 2px solid var(--bs-border-color, #dee2e6);
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2.5rem;
}

.avatar-url-display {
    max-width: 120px;
    word-break: break-all;
    text-align: center;
    font-size: 0.75rem;
}

.profile-fields {
    flex: 1;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

