toolArgs.file_text:
.preview-box {
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
    min-height: 180px;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-header {
    margin-bottom: 0.25rem;
}

.preview-compact .preview-text {
    margin-bottom: 0.25rem;
}

.preview-header {
    margin-bottom: 0.75rem;
    font-size: 1.1em;
}

.preview-text {
    margin-bottom: 1rem;
    opacity: 0.85;
}

.preview-actions {
    display: flex;
    gap: 1rem;
}

.preview-btn {
    padding: 0.25em 0.75em;
    border-radius: 0.25rem;
    background: var(--bs-primary, #0d6efd);
    color: #fff;
    font-size: 0.9em;
}

.preview-dark .preview-btn {
    background: #89b4fa;
    color: #1e1e2e;
}

.preview-link {
    padding: 0.25em 0;
    color: var(--bs-primary, #0d6efd);
    text-decoration: underline;
    font-size: 0.9em;
}

.preview-dark .preview-link {
    color: #89b4fa;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

